-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esES" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elemental"
L["rm.era.shaman.elemental.Description"] = "Elemental desde el nivel 10 (la mayoría de los puntos en Elemental); basada en Icy Veins y Wowhead. Choque de tierra interrumpe y remata a un objetivo a punto de morir. En movimiento: Choque de llamas y, si no, Choque de Escarcha. En solitario con el objetivo cuerpo a cuerpo: Choque de tierra por encima del 30 % de salud y después cuerpo a cuerpo. Contra tres o más enemigos: los tótems Nova de Fuego y de magma cuando estás cuerpo a cuerpo, y Cadena de relámpagos. Cadena de relámpagos con Maestría elemental o Conjuro libre y, si no, Descarga de relámpagos. Recordatorios: Escudo de relámpagos, Arma comerrocas fuera de bandas, Tótem abrasador o de magma, Tótem de fuente de maná o Tótem de corriente curativa, Maestría elemental con Cadena de relámpagos lista, Rapidez de la Naturaleza y Onda de curación por debajo del 30 %, y sanarte tras el combate. Las disipaciones, las purgas y usar rangos inferiores quedan a tu cargo."
L["rm.era.shaman.elemental.simulator.Name"] = "Elemental, Cadena de relámpagos cada vez que esté disponible (simulador)"
L["rm.era.shaman.elemental.simulator.Description"] = "La lista Elemental de simulador, una alternativa a la rotación integrada de Elemental recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Cadena de relámpagos cada vez que esté disponible, incluso contra un solo objetivo, Choque de tierra mientras Maestría elemental esté activa y, si no, Descarga de relámpagos. Más rápida, pero gasta mucho más maná que la rotación integrada recomendada; la misma interrupción, tótems y recordatorios."
L["rm.era.shaman.enhancement.Name"] = "Mejora"
L["rm.era.shaman.enhancement.Description"] = "Niveles 1–60, también en reinos Hardcore y en modo de opción personal, y todo chamán sin mayoría de talentos; basada en Icy Veins, Wowhead y simulador. Descarga de relámpagos inicia el combate a distancia; Choque de tierra interrumpe. En bandas, solo Golpe de tormenta y Choque de Escarcha (huecos de perjuicios). Con tres o más enemigos luchando contra ti, los tótems Nova de Fuego y de magma. Después, Golpe de tormenta, Choque de tierra aprovechando el perjuicio de Golpe de tormenta o para rematar, Choque de llamas cuando vaya a durar entero, Choque de tierra mientras tengas la mitad del maná, y Descarga de relámpagos mientras estés fuera de alcance. Recordatorios: Arma comerrocas en solitario y Arma tótem Viento Furioso en mazmorras, Escudo de relámpagos, Fuerza de tótem de la Tierra, Tótem abrasador, Tótem Viento Furioso o Tótem gracia del aire, Tótem de fuente de maná o Tótem de corriente curativa, y sanarte tras el combate y en emergencias. Tótem Garra de piedra, Tótem Nexo Terrestre, alternar tótems y los beneficios raciales aparecen desactivados; las disipaciones, las purgas y los tótems de purificación quedan a tu cargo."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Mejora, Choque de llamas primero (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "La Mejora de Warcraft Tavern, una alternativa a la rotación integrada de Mejora recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Arma tótem Viento Furioso en cuanto la aprendes, Golpe de tormenta, Choque de llamas antes de cualquier choque directo y después Choque de tierra mientras tu amenaza sea baja, o Choque de Escarcha en grupo cuando ya sea alta; Tótem de magma y Cadena de relámpagos contra grupos de enemigos. Los mismos tótems y recordatorios que la rotación integrada recomendada."
L["rm.era.shaman.restoration.Name"] = "Restauración"
L["rm.era.shaman.restoration.Description"] = "Recuperación desde el nivel 10 (la mayoría de los puntos en Recuperación); basada en Icy Veins y Wowhead. Sobre tu objetivo amistoso: Onda de curación con Rapidez de la Naturaleza, Rapidez de la Naturaleza por debajo del 30 %, Onda inferior de curación por debajo del 40 %, Curar veneno o Curar enfermedad, Curación en cadena cuando tres miembros del grupo cerca de ti están por debajo del 85 % y, si no, Onda de curación por debajo del 90 %. Contra un enemigo, lucha: Choque de tierra para interrumpir, Cadena de relámpagos contra grupos de enemigos, Choque de llamas, Descarga de relámpagos a distancia y cuerpo a cuerpo. Recordatorios: Escudo de relámpagos y Arma comerrocas en solitario, Tótem de marea de maná en grupo, Tótem de fuente de maná, Fuerza de tótem de la Tierra y Tótem abrasador. Elegir a quién sanar, usar rangos inferiores y los tótems de tremor o de purificación quedan a tu cargo; mantener Forma curativa en el tanque aparece desactivado."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Restauración, Curación en cadena primero (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "La Restauración de Warcraft Tavern, una alternativa a la rotación integrada de Restauración recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Curación en cadena es la sanación para cualquiera por debajo del 90 %, con Onda inferior de curación para quien esté a punto de morir; Onda de curación es solo para un sanador asignado al tanque con Forma curativa (aparece desactivada). Las mismas curas, daño contra enemigos y recordatorios de tótems que la rotación integrada recomendada."
L["rm.forever.shaman.elemental.Name"] = "Elemental"
L["rm.forever.shaman.elemental.Description"] = "Elemental a distancia una vez que Elemental es tu árbol de talentos principal con 21 puntos (la fila de Ráfaga de lava), según Icy Veins (antes de eso, la rotación integrada de Mejora juega el híbrido cuerpo a cuerpo que recomiendan todas las guías). Inicia el combate con Descarga de relámpagos (Cadena de relámpagos contra un grupo de enemigos), en movimiento solo lanza instantáneos, usa Nova de Fuego y Cadena de relámpagos contra tres o más enemigos, mantiene Choque de llamas activo, Ráfaga de lava cada vez que esté disponible, Golpe de tormenta y Choque de tierra si conoces Golpe de tormenta, Nova de Fuego con Conjuro libre en grupo y después Descarga de relámpagos. Recordatorios: escudo, imbuición de arma, Tótem abrasador o Tótem de magma, tótems de grupo, Maestría elemental e interrupción. La salud y el maná están ocultos para los addons en Forever, así que curarte y parar para recuperar maná lo decides tú. Quedan a tu cargo: kitear con Nexo Terrestre, Choque de Escarcha, Purgar y los demás tótems."
L["rm.forever.shaman.enhancement.Name"] = "Mejora (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Mejora cuerpo a cuerpo del nivel 1 al 60, y la opción predeterminada para cualquier chamán antes de Ráfaga de lava o del Tótem de marea de maná. Inicia el combate con Descarga de relámpagos a distancia y después Golpe de tormenta cada vez que esté disponible, una Descarga de relámpagos instantánea con cinco acumulaciones de Arma vorágine, Nova de Fuego (con un tótem de fuego colocado) y Choque de llamas contra tres o más enemigos, Choque de tierra aprovechando el perjuicio de Golpe de tormenta, Choque de llamas en grupo y Choque de tierra cada vez que esté disponible; Descarga de relámpagos cubre el hueco mientras el objetivo está fuera de alcance. La salud y el maná están ocultos para los addons en Forever, así que curarte y parar para recuperar maná lo decides tú (la rotación integrada de Wowhead ahorra maná en su lugar). Recordatorios: imbuición de arma (Viento Furioso; si no, Lengua de Fuego; si no, Comerrocas), Escudo de agua o de relámpagos, la interrupción con Choque de tierra, Tótem abrasador o Tótem de magma, tótems de grupo, Ira del clarividente, Tótem Garra de piedra. Quedan a tu cargo: los preajustes de tótems, Choque de Escarcha, Purgar y los demás tótems."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Mejora, eficiente en maná (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "La Mejora de ahorro de maná de Wowhead y Mobalytics: el ataque automático hace el trabajo, Golpe de tormenta solo mientras no esté activa la regeneración de maná de Golpe de tormenta mejorado, sin Choque de tierra en la rotación (los choques sirven para iniciar el combate e interrumpir) y, en grupo o contra grupos de enemigos, Tótem abrasador con Nova de Fuego cada vez que esté disponible. Los mismos recordatorios de imbuición, escudo e interrupción que la rotación integrada de Icy Veins. Elígela en lugar de esa rotación integrada si te quedas sin maná. Es una alternativa a la rotación integrada de Mejora recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad."
L["rm.forever.shaman.restoration.Name"] = "Restauración"
L["rm.forever.shaman.restoration.Description"] = "Sanación una vez que Restauración es tu árbol de talentos principal con 16 puntos (la fila del Tótem de marea de maná), según Icy Veins. Con un objetivo amistoso: una Onda de curación instantánea una vez que uses Rapidez de la Naturaleza, Curar veneno y Curar enfermedad, Mareas vivas sobre un objetivo que no lo tenga, Curación en cadena en grupo y Onda de curación. Eliges a quién sanar seleccionándolo como objetivo; la salud y el maná están ocultos para los addons en Forever, así que cuándo usar Rapidez de la Naturaleza y Onda inferior de curación lo decides tú. Con un objetivo hostil y nadie a quien sanar: Nova de Fuego y Cadena de relámpagos contra grupos de enemigos, Golpe de tormenta y Choque de tierra si conoces Golpe de tormenta, Choque de llamas sobre élites y jefes, Descarga de relámpagos y después cuerpo a cuerpo. Recordatorios: Escudo de agua, la interrupción con Choque de tierra, Marea de maná y los tótems de beneficio de grupo. Quedan a tu cargo: usar rangos inferiores, los demás tótems, Purgar y Lobo fantasmal."
L["rm.mop.shaman.elemental.Name"] = "Recomendada"
L["rm.mop.shaman.elemental.Description"] = "Recomendada para Elemental desde el nivel 10, elegida en la especialización Elemental. El orden de Wowhead: una Descarga de relámpagos para iniciar el combate (Ráfaga de lava con Furia desatada), Desatar elementos con Furia desatada, Choque de llamas cuando falta o está a punto de agotarse sobre un objetivo que vaya a sobrevivir, Ráfaga de lava sobre Choque de llamas (y con cada Oleada de lava), Explosión elemental, Choque de tierra con seis cargas de Escudo de relámpagos mientras a Choque de llamas le queden 6 segundos, Cadena de relámpagos contra dos enemigos y Descarga de relámpagos. Con cuatro o más enemigos luchando contra ti: Tótem de Magma cuerpo a cuerpo, Ráfagas de lava gratuitas, Haz de lava durante Ascensión y Cadena de relámpagos. En movimiento solo muestra instantáneos. Recordatorios: Escudo de relámpagos, Arma Lengua de Fuego, Tótem abrasador, Tótem Elemental de Fuego contra élites y jefes, Maestría elemental, Ascensión tras una Ráfaga de lava, Presteza ancestral, Tótem Látigo de tormenta y Ansia de sangre en grupo, Corte de viento, Tormenta de truenos para el maná, e Ira del chamán y Cambio astral con poca salud. Terremoto y Tótem Elemental de Tierra están en la lista, pero desactivados. Quedan a tu cargo: Gracia del caminaespíritus, Choque de llamas sobre objetivos adicionales y dónde colocarte."
L["rm.mop.shaman.enhancement.Name"] = "Recomendada"
L["rm.mop.shaman.enhancement.Description"] = "Recomendada para Mejora desde el nivel 10, elegida en la especialización Mejora. El orden de Wowhead: Desatar elementos mientras te acercas, y después Desatar elementos con Furia desatada, Explosión elemental y Descarga de relámpagos con cinco de Arma vorágine (o intercaladas con tres cuando a tu siguiente golpe le falta más de un segundo), Explosión de tormenta durante Ascensión, Golpe de tormenta (Golpe primigenio antes del 26), Latigazo de lava, Choque de llamas con Desatar llama, Desatar elementos y Choque de tierra. Con dos o más enemigos luchando contra ti: Cadena de relámpagos en lugar de Descarga de relámpagos, Latigazo de lava para extender Choque de llamas, Nova de Fuego desde cuatro y Tótem de Magma desde seis. Recordatorios: Escudo de relámpagos, Arma Viento Furioso en la mano principal y Arma Lengua de Fuego en la secundaria, Tótem abrasador, Tótem Elemental de Fuego, Espíritu feral, Ascensión tras Golpe de tormenta, Maestría elemental, Presteza ancestral, Tótem Látigo de tormenta y Ansia de sangre en grupo, Corte de viento, e Ira del chamán y Cambio astral con poca salud. Tótem Elemental de Tierra está en la lista, pero desactivado."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Latigazo de lava primero (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Mejora recomendada, así que actívala y desactiva la otra para usarla. El orden de Icy Veins: Golpe de tormenta, después Latigazo de lava antes de gastar Arma vorágine, Descarga de relámpagos con cinco acumulaciones o desde tres cuando impacta antes de tu siguiente golpe, Desatar elementos y después Choque de llamas, y Choque de tierra. Contra cuatro o más enemigos extiende Choque de llamas con Latigazo de lava y usa Nova de Fuego; Cadena de relámpagos sustituye a Descarga de relámpagos contra grupos de enemigos. Ira del chamán se sugiere cada vez que esté disponible en combate; los demás recordatorios, como en la rotación integrada recomendada."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Intercalar con cada acumulación (simulador)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Mejora recomendada, así que actívala y desactiva la otra para usarla. La lista del simulador para quienes sincronizan los lanzamientos entre golpes: Descarga de relámpagos, Explosión elemental o Cadena de relámpagos con cualquier número de acumulaciones de Arma vorágine siempre que el lanzamiento termine antes de tu siguiente golpe con la mano principal, Desatar elementos también siempre que falte Choque de llamas, y Choque de tierra solo por debajo de dos acumulaciones. Recordatorios como en la rotación integrada recomendada."
L["rm.mop.shaman.restoration.Name"] = "Recomendada"
L["rm.mop.shaman.restoration.Description"] = "Recomendada para Restauración desde el nivel 10, elegida en la especialización Restauración. Sana a tu objetivo amistoso (Rotation Master no puede elegir a quién sanar): Ola de sanación superior con Presteza ancestral, Oleada de sanación por debajo del 35 %, Purificar espíritu contra magia o maldiciones, Desatar elementos y después Lluvia de sanación cuando hay tres aliados heridos cerca, Mareas Vivas, Sanación en cadena para daño de grupo, Ola de sanación superior por debajo del 60 % y Ola de sanación por debajo del 90 %. Con un objetivo atacable hace daño en su lugar (Choque de llamas, Ráfaga de lava, Explosión elemental, Descarga de relámpagos). Recordatorios: Escudo de agua, Arma de Vida terrestre, Escudo de tierra sobre tu foco, Tótem Corriente de sanación cuando alguien está herido, Tótem Marea de maná, Tótem de Marea de sanación para daño de grupo fuerte, Maestría elemental o Guía ancestral, Presteza ancestral sobre un objetivo con poca salud, Gracia del caminaespíritus en movimiento, Ansia de sangre y Corte de viento. Ascensión y Tótem Enlace de espíritu están en la lista, pero desactivados: úsalos cuando tu banda te los asigne."
L["rm.mop.shaman.restoration.hekili.Name"] = "Escala de salud (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Restauración recomendada, así que actívala y desactiva la otra para usarla. La lista de Hekili mantiene Escudo de tierra y Mareas Vivas sobre tu objetivo, y Tótem Corriente de sanación y Lluvia de sanación siempre que no estén activos, y después sana según la salud media de tu grupo en un radio de 40 metros: Sanación en cadena por debajo del 80 %, Ola de sanación sobre un objetivo por debajo del 70 %, Ola de sanación superior por debajo del 60 % y Oleada de sanación por debajo del 40 %, con Tótem de Marea de sanación, Guía ancestral y Tótem Marea de maná en la misma escala. Un objetivo atacable recibe daño más Choque de tierra."
L["rm.mop.shaman.unspecialized.Name"] = "Sin especialización"
L["rm.mop.shaman.unspecialized.Description"] = "Para los niveles 1 a 9, y cualquier chamán que aún no haya elegido especialización; la rotación integrada de cada especialización toma el relevo en cuanto eliges una. Descarga de relámpagos para iniciar el combate a distancia, Oleada de sanación cuando tienes poca salud y estás solo, Golpe primigenio, Choque de tierra, y Descarga de relámpagos mientras estés fuera del alcance cuerpo a cuerpo. Mantiene activo Escudo de relámpagos."
L["rm.retail.shaman.elemental.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Recomendada para Elemental en Midnight. En combate, el juego ahora oculta a los addons Choque de llamas, tus beneficios, la Vorágine, los tiempos de reutilización y la salud, así que esta rotación muestra la propia sugerencia del Ayudante de combate de Blizzard (la rotación de un solo botón), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: Ascensión, Elemental de Fuego o Elemental de tormenta y Presteza de la Naturaleza en combate, Gracia del caminaespíritus en movimiento, Escudo de relámpagos y Furia del cielo entre combates (la sugerencia de Blizzard mantiene las imbuiciones de arma y de escudo), Corte de viento ante un lanzamiento interrumpible (solo se ilumina donde el juego permite leer el lanzamiento), Cambio astral siempre que esté listo en combate (la salud está oculta en Retail, así que cuándo usarlo lo decides tú)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Referencia (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft lee Choque de llamas, Maestro de los elementos y Guardia de la Tormenta, que Midnight oculta en combate; la Vorágine está oculta en Retail, así que las habilidades de gasto se usan por su coste en lugar de con la Vorágine casi llena. Guardia de la Tormenta y Ráfaga de lava antes de iniciar el combate. Contra tres o más enemigos trabados en combate: Guardia de la Tormenta, Presteza ancestral, Choque de llamas, Cadena de relámpagos con Guardia de la Tormenta, Explosión elemental, Terremoto, Ráfaga de lava con Oleada de lava, Tempestad, Cadena de relámpagos. Si no, Guardia de la Tormenta, Presteza ancestral, Choque de llamas y Llamarada voltaica en su último 30 % fuera de Maestro de los elementos, Ráfaga de lava para activarlo, Tempestad y la Descarga de relámpagos de Guardia de la Tormenta dentro de él, Explosión elemental o Choque de tierra dentro de él, Llamarada voltaica, Tempestad, Choque de llamas o Choque de Escarcha en movimiento, Explosión elemental o Choque de tierra siempre que puedas permitírtelo, Descarga de relámpagos. Recordatorios: Ascensión una vez usado Guardia de la Tormenta, los elementales, Gracia del caminaespíritus y los compartidos."
L["rm.retail.shaman.enhancement.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Recomendada para Mejora en Midnight. Muestra la sugerencia del Ayudante de combate de Blizzard (gasta las acumulaciones de Arma vorágine, mantiene Choque de llamas y se encarga de Tótem emergente y Hendimiento), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: Ascensión, Vientos de fatalidad y Espíritu feral en combate, Escudo de relámpagos y Furia del cielo entre combates (la sugerencia de Blizzard mantiene Arma Viento furioso), Corte de viento, Cambio astral."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Invocatormentas (referencia de SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Solo de referencia, desactivada por defecto: la lista de Invocatormentas de SimulationCraft (Icy Veins y Wowhead coinciden) lee Choque de llamas, Estallido de relámpagos, Llamas lacerantes y los temporizadores de los tiempos de reutilización, que Midnight oculta en combate. Contra tres o más enemigos trabados en combate: Estallido de relámpagos por su beneficio, Tempestad con 10 acumulaciones de Arma vorágine, Cadena de relámpagos con 9, Estallido de relámpagos, Latigazo de lava, Hendimiento. Después, Tormenta primigenia con 9, Llamarada voltaica o Choque de llamas cuando falta Choque de llamas, Hendimiento, Estallido de relámpagos por su beneficio, Latigazo de lava para Llamas lacerantes, Golpe de viento, Tempestad o Descarga de relámpagos con 10 (8 si Llamarada voltaica o Estallido de relámpagos están a punto de estar listos), Golpe de tormenta con dos cargas, Latigazo de lava, Golpe de tormenta, Llamarada voltaica, Estallido de relámpagos, Descarga de relámpagos con 5, Choque de llamas. Recordatorios: Vientos de fatalidad, Ascensión fuera de Vientos de fatalidad, Espíritu feral y los compartidos."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totémico (referencia de SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Solo de referencia, desactivada por defecto: la lista de Totémico de SimulationCraft lee Choque de llamas, Mano caliente, Torbellino de fuego, Estallido de relámpagos y Vientos de fatalidad, que Midnight oculta en combate. Contra tres o más enemigos trabados en combate: Estallido de relámpagos, Cadena de relámpagos con 5 acumulaciones de Arma vorágine. Después, Llamarada voltaica o Choque de llamas cuando falta Choque de llamas, Tótem emergente, Hendimiento, Latigazo de lava con Mano caliente o Torbellino de fuego, Estallido de relámpagos por su beneficio, Tormenta primigenia con 10, Golpe de viento, Estallido de relámpagos y Golpe de tormenta durante Vientos de fatalidad, Descarga de relámpagos con 5, Estallido de relámpagos, Latigazo de lava, Golpe de tormenta, Llamarada voltaica, Choque de llamas. Los mismos recordatorios que la referencia de Invocatormentas."
L["rm.retail.shaman.initial.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.shaman.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del chamán). Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de chamán, cada uno cuando conoces su hechizo. Cuando elijas una especialización a nivel 10, las rotaciones integradas de esa especialización toman el relevo."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Restauración en Midnight, como referencia: el Ayudante de combate de Blizzard no cubre a los sanadores, el juego oculta la salud de todos en combate y Rotation Master elige un hechizo, no un objetivo, así que esta rotación ordena tus herramientas de sanación según su disponibilidad sobre lo que tengas como objetivo, y deja a tu cargo decidir a quién sanar. Sobre un objetivo amistoso: Tótem Corriente de sanación, Desatar vida, Lluvia de sanación en grupo, Tótem emergente, Mareas vivas, Sanación en cadena en grupo, Ola de sanación. Sobre un enemigo: Choque de llamas cuando falta, Ráfaga de lava, Descarga de relámpagos. Recordatorios: Escudo de agua, Escudo de tierra sobre un objetivo amistoso y Furia del cielo entre combates; Presteza de la Naturaleza en combate; Tótem de Marea de sanación y Tótem Enlace de espíritu en combate en grupo; Corte de viento; Cambio astral."
L["rm.sod.shaman.elemental.Name"] = "Elemental (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Elemental de la Temporada del Descubrimiento desde el nivel 10 (la mayoría de los puntos en Elemental); basada en la fase 6 de simulador, Wowhead e Icy Veins. Choque de tierra interrumpe. En movimiento: Choque de llamas, Choque de tierra con ocho cargas de Escudo de relámpagos, y Ráfaga de lava o Cadena de relámpagos cuando se activa Oleada de poder. Contra tres o más enemigos: Choque de llamas, Cadena de relámpagos, Nova de Fuego, Ráfaga de lava, Choque de tierra con ocho cargas y Tótem de magma. Después, Ráfaga de lava con Oleada de poder, Choque de llamas siempre activo, Ráfaga de lava mientras dure tu Choque de llamas, Choque de tierra con ocho cargas, Cadena de relámpagos contra dos enemigos y Descarga de relámpagos. Recordatorios: Arma lengua de Fuego para Quemar, Escudo de relámpagos, Escudo de tierra sobre ti, Espíritu del alfa, Espíritu feral, Ira del chamán, Maestría elemental y tótems. Las alhajas, Proyección totémica, las disipaciones y las purgas quedan a tu cargo."
L["rm.sod.shaman.enhancement.Name"] = "Mejora (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Temporada del Descubrimiento, niveles 1–60 con las runas a medida que las grabas, con dos armas o con un arma a dos manos, y todo chamán de la Temporada del Descubrimiento al que no se ajuste ninguna otra rotación integrada; basada en la fase 6 de simulador, Icy Veins y Wowhead. Choque de llamas inicia el combate; Choque de tierra interrumpe. Contra tres o más enemigos: Tótem de magma, Nova de Fuego con un tótem de fuego, Cadena de relámpagos con cuatro acumulaciones de Arma vorágine y Choque de llamas. Después, Ráfaga de lava con cinco acumulaciones de Arma vorágine, Golpe de tormenta, Latigazo de lava, Descarga de relámpagos con cinco acumulaciones, Choque de llamas cuando vaya a durar, Choque de tierra, Explosión de arrabio y Descarga de relámpagos a distancia. Recordatorios: Arma tótem Viento Furioso (antes, Arma comerrocas), Arma lengua de Fuego en un arma de la mano secundaria con Latigazo de lava (si no, Viento Furioso; nunca en un escudo; una línea de Icy Veins con Viento Furioso en ambas aparece desactivada), Escudo de agua o de relámpagos, Espíritu del alfa, Espíritu feral, Ira del chamán por debajo del 65 % de maná, tótems y Guía ancestral. Proyección totémica, las disipaciones y las purgas quedan a tu cargo."
L["rm.sod.shaman.restoration.Name"] = "Restauración (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Recuperación de la Temporada del Descubrimiento desde el nivel 10 (la mayoría de los puntos en Recuperación); basada en Icy Veins y Wowhead. Sobre tu objetivo amistoso: Mareas vivas y después Onda inferior de curación por debajo del 40 %, Curar veneno o Curar enfermedad, Lluvia de sanación cuando tres miembros del grupo cerca de ti están por debajo del 85 %, Curación en cadena cuando lo están dos (al instante cuando se activa Oleada de poder), Mareas vivas por debajo del 95 % para Maremotos y Onda de curación por debajo del 90 %. Contra un enemigo, lucha. Recordatorios: Escudo de agua (antes, Escudo de relámpagos), Escudo de tierra sobre tu objetivo amistoso o sobre ti, Ira del chamán, Tótem de marea de maná, Tótem de fuente de maná y Fuerza de tótem de la Tierra. Elegir a quién sanar y los tótems de tremor o de purificación quedan a tu cargo."
L["rm.sod.shaman.tank.Name"] = "Tanque (SoD, Camino de la tierra)"
L["rm.sod.shaman.tank.Description"] = "Tanque de la Temporada del Descubrimiento, elegida una vez que Camino de la tierra está grabado; basada en Icy Veins, Wowhead, simulador y Warcraft Tavern. Choque de llamas inicia el combate. Choque de tierra provoca a un objetivo cuerpo a cuerpo que no te está atacando, e interrumpe. Contra dos o más enemigos: Explosión de arrabio, Choque de llamas, Cadena de relámpagos con cinco acumulaciones de Arma vorágine o con Oleada de poder, y Nova de Fuego con cinco acumulaciones. Después, Choque de llamas siempre activo, Ráfaga de lava con Oleada de poder o mientras dure Choque de llamas, Golpe de tormenta, Choque de tierra, Descarga de relámpagos con cinco acumulaciones, Explosión de arrabio y Choque de Escarcha. Recordatorios: Arma comerrocas, Escudo de relámpagos, Espíritu del alfa sobre ti, Espíritu feral, Ira del chamán, Tótem abrasador o de magma, y los tótems de grupo."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elemental (Icy Veins y simulador)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Elemental a distancia para el árbol de talentos Elemental. Descarga de relámpagos es el relleno; Cadena de relámpagos se lanza con Maestría elemental, con Lanzamiento libre mientras tengas un 40 % de maná, o libremente por encima del 80 %; Choque de llamas solo en movimiento; Choque de tierra interrumpe; Nova de Fuego, Cadena de relámpagos y magma contra grupos de enemigos. Antes de Cadena de relámpagos, a un objetivo cuerpo a cuerpo se le deja con el ataque automático para ahorrar maná. Recordatorios: Escudo de agua o de relámpagos, una imbuición de arma, Tótem de cólera (o Tótem abrasador en combates largos), Cólera de aire, Fuente de maná, Llamada totémica tras el combate, Maestría elemental y Ansia de sangre/Heroísmo."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elemental (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "El Elemental de NextActionTBC, una alternativa a la rotación integrada de Elemental de Icy Veins recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Mantiene Choque de llamas en el objetivo, Cadena de relámpagos solo contra dos o más enemigos mientras tengas más del 30 % de maná, y Descarga de relámpagos en los demás casos. Te recuerda Escudo de relámpagos, una imbuición de arma, Maestría elemental y Ansia de sangre/Heroísmo; los tótems siguen siendo manuales."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elemental (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "El Elemental de Wowhead, una alternativa a la rotación integrada de Elemental de Icy Veins recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. A nivel 70, Cadena de relámpagos cada vez que esté disponible con Descargas de relámpagos entre medias (durante la subida de nivel, solo con Maestría elemental o Lanzamiento libre), Choque de llamas solo en movimiento y Choque de tierra para rematar a un objetivo que moriría antes de completar un lanzamiento. Los mismos recordatorios de tótems, escudos y tiempos de reutilización que la variante de Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Mejora (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Mejora cuerpo a cuerpo del nivel 1 al 70, y la opción predeterminada para cualquier chamán al que no se ajuste ninguna otra rotación integrada. Inicia el combate con Descarga de relámpagos a distancia, interrumpe con Choque de tierra, coloca los tótems Nova de Fuego y de magma con tres o más enemigos cerca, y después Golpe de tormenta, Choque de tierra mientras dure el perjuicio de Golpe de tormenta, Choque de llamas sobre un objetivo que vaya a sobrevivir, Choque de tierra cada vez que esté disponible y Descarga de relámpagos mientras el objetivo esté fuera de alcance. Recordatorios aparte: imbuiciones de arma, Escudo de agua o de relámpagos, Fuerza de la tierra, Viento Furioso (en grupo) o Gracia del aire (en solitario), Tótem abrasador en combates largos, tótems de agua, Ira del chamán, Ansia de sangre/Heroísmo contra jefes, y Garra de piedra y Elemental de Tierra en solitario. Elemental de Fuego es un paso opcional que empieza desactivado. La colocación de tótems, Lobo fantasmal y la sanación quedan a tu cargo."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Mejora (Wowhead y simulador)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "El modelo de banda de nivel 70 para alternar tótems, una alternativa a la rotación integrada de Mejora de Icy Veins recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Golpe de tormenta, intercalar el Tótem Nova de Fuego, Choque de llamas siempre que haya desaparecido y Choque de tierra como choque principal, con Descarga de relámpagos solo fuera de alcance. Los recordatorios alternan los tótems Viento Furioso y Gracia del aire, mantienen colocado el Tótem abrasador, usan Ira del chamán cuando escasea el maná y comparten con la variante de Icy Veins el mantenimiento de imbuiciones, escudos y tótems."
L["rm.tbc.shaman.restoration.Name"] = "Restauración"
L["rm.tbc.shaman.restoration.Description"] = "Sanación para el árbol de talentos Restauración, sobre tu objetivo amistoso (o sobre ti si no tienes objetivo): Presteza de la Naturaleza y Ola de sanación u Ola de sanación inferior en emergencias, Curar envenenamiento y Curar enfermedad, Escudo de tierra sobre tu foco, Sanación en cadena cuando hay tres aliados heridos cerca y Ola de sanación en los demás casos. Con un objetivo hostil cambia a Choque de llamas y Descarga de relámpagos para jugar en solitario. Recordatorios: Escudo de agua, Escudo de tierra sobre tu foco (pon al tanque como foco), Marea de maná, Fuente de maná y Fuerza de la tierra en grupo, Ansia de sangre/Heroísmo. Elegir a quién sanar y con qué rango queda a tu cargo."
